Method.Source:
    /// <summary>
    /// Get item sales unit.
    /// First check if there is a default order setting specific for the site or blank site
    /// Otherwise get it from the released product
    /// </summary>
    /// <param name = "_itemId">Item id</param>
    /// <param name = "_inventDimId">Inventory dimension Id</param>
    /// <returns>Container with item sales unit and the default order setting record if any</returns>
    static container METGetSalesUnit(ItemId       _itemId,
                                     InventDimId  _inventDimId)
    {
        UnitOfMeasureSymbol salesUnit;

        // search for a site or the default record (site and no site)
        InventItemSalesSetup salesSetup = InventItemSalesSetup::find(_itemId, _inventDimId);

        salesUnit = (salesSetup && salesSetup.METSalesUnit) ? salesSetup.METSalesUnit :
                                                              InventTableModule::find(_itemId, ModuleInventPurchSales::Sales).UnitId;
        
        return [salesSetup, salesUnit];
    }
